import sys

def base36_encode(n):
    """Encode an integer as a base-36 string (0-9, A-Z)."""
    chars = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    if n == 0:
        return '0'
    result = []
    while n > 0:
        result.append(chars[n % 36])
        n //= 36
    return ''.join(reversed(result))


def base36_decode(s):
    """Decode a base-36 string to an integer."""
    return int(s, 36)


def next_id(last_id):
    """Given an ID like 'ORD-243G', return the next ID like 'ORD-243H'."""
    prefix, suffix = last_id.rsplit('-', 1)
    n = base36_decode(suffix)
    n += 1
    next_suffix = base36_encode(n).zfill(4)
    return f'{prefix}-{next_suffix}'


def main():
    # Read ids.txt, find the last non-empty order ID
    last_id = None
    with open('ids.txt') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split('\t')
            if len(parts) >= 2 and parts[1].strip():
                last_id = parts[1].strip()

    if last_id is None:
        print('ORD-0000')
    else:
        print(next_id(last_id))


if __name__ == '__main__':
    main()

