from pathlib import Path


def to_base36(n: int) -> str:
    """Convert an integer to a zero-padded 4-char base-36 string."""
    chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    result = ""
    for _ in range(4):
        result = chars[n % 36] + result
        n //= 36
    return result


def from_base36(s: str) -> int:
    """Convert a 4-char base-36 string to an integer."""
    return int(s, 36)


def main() -> None:
    lines = Path("ids.txt").read_text(encoding="utf-8").strip().splitlines()
    if not lines:
        raise SystemExit("error: ids.txt is empty")

    last_id = lines[-1].strip()
    if not last_id.startswith("ORD-") or len(last_id) != 8:
        raise SystemExit(f"error: unexpected id format: {last_id!r}")

    suffix = last_id[4:]
    num = from_base36(suffix)
    next_suffix = to_base36(num + 1)
    print(f"ORD-{next_suffix}")


if __name__ == "__main__":
    main()

def increment_id(suffix):
    """Increment a base-36 4-character string by 1."""
    chars = list(suffix)
    for i in range(3, -1, -1):
        c = chars[i]
        if '0' <= c <= '8':
            chars[i] = chr(ord(c) + 1)
            break
        elif c == '9':
            chars[i] = 'A'
            break
        elif 'A' <= c <= 'Y':
            chars[i] = chr(ord(c) + 1)
            break
        elif c == 'Z':
            chars[i] = '0'
            # carry continues to next position
        else:
            raise ValueError(f"Unexpected character: {c}")
    else:
        # All positions were Z -> wrap around to 0000
        chars = ['0', '0', '0', '0']
    return ''.join(chars)


def main():
    with open('ids.txt') as f:
        lines = [line.strip() for line in f if line.strip()]

    if not lines:
        print('ORD-0000')
        return

    last_id = lines[-1]
    prefix = last_id[:4]  # "ORD-"
    suffix = last_id[4:]  # 4 characters

    next_suffix = increment_id(suffix)
    print(f'{prefix}{next_suffix}')


if __name__ == '__main__':
    main()

