#!/usr/bin/env python3
"""Read the most recent order id from ids.txt and print the next one."""

import sys

BASE36_CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_base36(n: int) -> str:
    """Convert non-negative integer to uppercase base36 (no padding)."""
    if n == 0:
        return "0"
    result = ""
    while n > 0:
        result = BASE36_CHARS[n % 36] + result
        n //= 36
    return result


def next_id(last_id: str) -> str:
    """Given an id like ORD-243G, return the next in sequence (base36)."""
    s = last_id.strip()
    if not s.startswith("ORD-") or len(s) != 8:
        sys.exit(f"Error: unexpected id format {s!r}")
    suffix = s[4:]
    val = int(suffix, 36) + 1
    return f"ORD-{to_base36(val).zfill(4)}"


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        sys.exit("Error: ids.txt not found")

    if not lines:
        print("ORD-0000")
        return

    print(next_id(lines[-1]))


if __name__ == "__main__":
    main()

