"""Generate manifest.json with SHA-256 hex digests for all files under release/."""

import hashlib
import json
from pathlib import Path

RELEASE_DIR = Path(__file__).resolve().parent / "release"
MANIFEST_PATH = Path(__file__).resolve().parent / "manifest.json"


def sha256_hex(path: Path) -> str:
    """Return the SHA-256 hex digest of a file."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        while True:
            chunk = f.read(8192)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest = {}
    # Walk through release/ relative to the repo root.
    for p in sorted(RELEASE_DIR.rglob("*")):
        if p.is_file():
            # e.g. "release/app/main.py"
            rel = str(p.relative_to(RELEASE_DIR.parent))
            manifest[rel] = sha256_hex(p)

    with open(MANIFEST_PATH, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")  # trailing newline

    print(f"Wrote {MANIFEST_PATH}")


if __name__ == "__main__":
    main()

