#!/usr/bin/env python3
"""Generate manifest.json: a map of release/ file paths to their SHA-256 hex digests."""

import hashlib
import json
import os

RELEASE_DIR = "release"
MANIFEST_FILE = "manifest.json"


def hash_file(path: str) -> str:
    """Return the SHA-256 hex digest of *path*."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()


def main() -> None:
    manifest: dict[str, str] = {}

    for dirpath, _dirnames, filenames in os.walk(RELEASE_DIR):
        for fn in filenames:
            full = os.path.join(dirpath, fn)
            rel = os.path.relpath(full)  # e.g. release/app/main.py
            manifest[rel] = hash_file(full)

    # Sort keys for deterministic output.
    manifest = dict(sorted(manifest.items()))

    with open(MANIFEST_FILE, "w") as f:
        json.dump(manifest, f, indent=2)
        f.write("\n")

    print(f"Wrote {MANIFEST_FILE} with {len(manifest)} entries.")


if __name__ == "__main__":
    main()

