#!/usr/bin/env python3
"""List reports/ filenames in report order (ascending by the numeric suffix)."""

import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")

def report_sort_key(filename: str) -> int:
    """Extract the numeric part from a filename like 'report-3.txt'."""
    m = re.search(r"(\d+)", filename)
    return int(m.group(1)) if m else 0

def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = sorted(
        (e for e in entries if os.path.isfile(os.path.join(REPORTS_DIR, e))),
        key=report_sort_key,
    )
    for r in reports:
        print(r)

if __name__ == "__main__":
    main()

