ARCHIVE_LOG = "archive.log"
TS_FORMAT = "%Y-%m-%d %H:%M:%S"
SEVEN_DAYS = 7 * 24 * 60 * 60


def entry_timestamp(line):
    """Return epoch seconds for the line's leading timestamp, or None."""
    try:
        dt = datetime.strptime(line[:19], TS_FORMAT).replace(tzinfo=timezone.utc)
        return dt.timestamp()
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        sys.stderr.write("usage: python rotate.py AS_OF\n")
        sys.exit(1)

