import sys
import os
from datetime import datetime, timezone

ROOT = os.path.dirname(os.path.abspath(__file__))
APP_LOG = os.path.join(ROOT, "app.log")
ARCHIVE_LOG = os.path.join(ROOT, "archive.log")

def parse_line_ts(line: str):
    """Parse 'YYYY-MM-DD HH:MM:SS' prefix and return epoch seconds, or None."""
    if len(line) < 19:
        return None
    try:
        dt = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
        return dt.replace(tzinfo=timezone.utc).timestamp()
    except ValueError:
        return None

def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    threshold = as_of - 7 * 86400  # 7 days in seconds

    if not os.path.exists(APP_LOG):
        print(f"{APP_LOG} not found", file=sys.stderr)
        sys.exit(1)

    with open(APP_LOG, "r") as f:
        lines = f.readlines()

    keep = []
    move = []
    for line in lines:
        if not line.strip():
            keep.append(line)
            continue
        ts = parse_line_ts(line)
        if ts is not None and ts < threshold:
            move.append(line)
        else:
