#!/usr/bin/env python3
"""Rotate entries in app.log older than 7 days before AS_OF to archive.log."""

import sys
import time
from datetime import datetime, timezone


def parse_timestamp(line: str):
    """Parse 'YYYY-MM-DD HH:MM:SS' prefix from a log line, return (dt, rest)."""
    if len(line) < 19 or line[4] != '-' or line[7] != '-' or line[10] != ' ' or line[13] != ':' or line[16] != ':':
        return None, line
    ts_str = line[:19]
    try:
        dt = datetime.strptime(ts_str, '%Y-%m-%d %H:%M:%S').replace(tzinfo=timezone.utc)
        return dt, line[19:]
    except ValueError:
        return None, line


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print(f"Error: AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 24 * 3600  # 7 days in seconds

    with open('app.log', 'r') as f:
        lines = f.readlines()

    kept = []
    archived = []

    for line in lines:
        dt, rest = parse_timestamp(line)
        if dt is not None:
            entry_ts = int(dt.timestamp())
            if entry_ts < cutoff:
                archived.append(line)
            else:
                kept.append(line)
        else:
            # If we can't parse timestamp, keep it in app.log
            kept.append(line)

    # Append archived entries to archive.log
    if archived:
        with open('archive.log', 'a') as f:
            f.writelines(archived)

    # Rewrite app.log with kept entries (preserve trailing newline if any)
    with open('app.log', 'w') as f:
        f.writelines(kept)


if __name__ == '__main__':
    main()

