Usage: python rotate.py AS_OF

AS_OF is a Unix timestamp in integer seconds. Every line of app.log that is
strictly older than 7 days before AS_OF is moved to archive.log (appended,
preserving order). app.log is rewritten with the remaining entries.
"""

import os
import sys
from datetime import datetime, timedelta, timezone


ROOT = os.path.dirname(os.path.abspath(__file__))
APP_LOG = os.path.join(ROOT, "app.log")
ARCHIVE_LOG = os.path.join(ROOT, "archive.log")


def parse_ts(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' from the start of a line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = datetime.fromtimestamp(int(sys.argv[1]), tz=timezone.utc)
    except (ValueError, OSError):
